import { createHash } from 'node:crypto';

import type { Client } from '@libsql/client';

/** A migration generated by drizzle-kit (`vp run db:generate`). */
export interface Migration {
	tag: string;
	/** The journal's `when`: migrations newer than the last applied one run */
	createdAt: number;
	hash: string;
	statements: string[];
}

/** Reads a file of the migrations folder, by its path relative to that folder. */
export type MigrationReader = (file: string) => Promise<string | undefined>;

// Same bookkeeping as drizzle-orm's migrator, so drizzle-kit and studio agree with it
const migrationsTable = '__drizzle_migrations';
const statementBreakpoint = '--> statement-breakpoint';

/**
 * Reads the migrations listed in drizzle-kit's journal. drizzle-orm's own migrator
 * only reads a folder on disk, which the server bundle does not have: the files are
 * Nitro server assets instead, so the source is a parameter.
 */
export async function loadMigrations(read: MigrationReader): Promise<Migration[]> {
	const journal = await read('meta/_journal.json');
	if (journal === undefined) {
		throw new Error('Missing migrations journal meta/_journal.json');
	}

	const migrations: Migration[] = [];
	for (const entry of parseJournal(journal)) {
		const sql = await read(`${entry.tag}.sql`);
		if (sql === undefined) {
			throw new Error(`Missing migration file ${entry.tag}.sql`);
		}
		migrations.push({
			tag: entry.tag,
			createdAt: entry.when,
			hash: createHash('sha256').update(sql).digest('hex'),
			statements: sql
				.split(statementBreakpoint)
				.map((statement) => statement.trim())
				.filter((statement) => statement !== ''),
		});
	}
	return migrations;
}

/**
 * Applies the migrations newer than the last applied one, all in one transaction.
 * Returns the migrations that were applied.
 */
export async function applyMigrations(
	client: Client,
	migrations: Migration[],
): Promise<Migration[]> {
	await client.execute(
		`CREATE TABLE IF NOT EXISTS "${migrationsTable}" (id SERIAL PRIMARY KEY, hash text NOT NULL, created_at numeric)`,
	);
	const last = await client.execute(
		`SELECT created_at FROM "${migrationsTable}" ORDER BY created_at DESC LIMIT 1`,
	);
	const lastCreatedAt = Number(last.rows[0]?.['created_at'] ?? Number.NEGATIVE_INFINITY);

	const pending = migrations.filter((migration) => migration.createdAt > lastCreatedAt);
	if (pending.length === 0) {
		return [];
	}

	// client.migrate runs the batch in a transaction with foreign keys off,
	// which table rebuilds generated by drizzle-kit need
	await client.migrate(
		pending.flatMap((migration) => [
			...migration.statements,
			{
				sql: `INSERT INTO "${migrationsTable}" (hash, created_at) VALUES (?, ?)`,
				args: [migration.hash, migration.createdAt],
			},
		]),
	);
	return pending;
}

interface JournalEntry {
	tag: string;
	when: number;
}

function parseJournal(json: string): JournalEntry[] {
	const journal: unknown = JSON.parse(json);
	const entries =
		typeof journal === 'object' && journal !== null && 'entries' in journal
			? journal.entries
			: undefined;
	if (!Array.isArray(entries) || !entries.every(isJournalEntry)) {
		throw new Error('Invalid migrations journal meta/_journal.json');
	}
	return entries;
}

function isJournalEntry(value: unknown): value is JournalEntry {
	return (
		typeof value === 'object' &&
		value !== null &&
		'tag' in value &&
		typeof value.tag === 'string' &&
		'when' in value &&
		typeof value.when === 'number'
	);
}
